// TH16 v1.00a Extra Stage midboss spell 2 (双中Boss 第2符 狂舞「クレイジーバックダンス」).
// Source: st07mbs.ecl.txt MBossCard2:293-330 (+ MBossCard2_at:398-429,
//         MBossCard2_ECir00:348-372, MBossCard2_ECir00_at:374-396),
//         st07mbs2.ecl.txt MBossBCard2:235-269.
// Source entry sits after the level-side setup: MBoss at (80,128), MBossB at (-80,128),
// both stopped by moveVel/movePosTime(0). Card window 3000 frames (spellEx/setInterrupt).

const TIME_LIMIT: int = 3124;   // 120 shell buffer + 3000 source + 4 startup slack
const OPENING_BUFFER: int = 120;

// 0.034906585 rad/frame = 2 deg = 364.09 BAM
const MB2_OMEGA: int = 364;
// F0 increments by 0.174533 rad = 10 deg per spawned pair
const MB2_PHASE_STEP: int = 1820;

// st07mbs.ecl.txt:398-429 MBossCard2_at
async sub mb2_spawner() {
    var a: fx = 160fx;
    var phase: int = 0;
    var elapsed: int = 90;      // entry -> first pair (source +90 label)
    var step: int = 0;          // 0..13; source does 7 shrinking then 7 growing pairs
    while elapsed < 3000 {
        if step == 0 { a = 160fx; }
        _ = spawn_enemy(a, 480fx, 100, 0, 0, 0, mb2_cir(a, phase));
        _ = spawn_enemy(0fx - a, 480fx, 100, 0, 0, 0, mb2_cir(0fx - a, phase));
        if step < 7 { a = a - 24fx; } else { a = a + 24fx; }
        phase = phase + MB2_PHASE_STEP;
        step = step + 1;
        if step == 14 { step = 0; }
        wait(30);
        elapsed = elapsed + 30;
    }
}

// st07mbs.ecl.txt:348-396 MBossCard2_ECir00 + MBossCard2_ECir00_at.
// Absolute position (x,480) moving up at speed 2 with a REL ellipse of radius 32;
// the async shooter (first shot 10+RAND%30, then every 20, 400 total) is merged here so
// the position update and the shot keep the source order (movement before the shot).
async sub mb2_cir(x: fx, phase: int) {
    set_invuln(65535);
    set_hurtbox(12fx);          // setHurtbox(24,24)
    set_hitbox(8fx);            // setHitbox(16,16)
    wait(60);
    // t=60: moveVel(-pi/2,2) + moveEllipseRel(F0, 2deg, 32, 0, pi/4, 1); setter places REL now.
    var abs_y: fx = 480fx;
    var theta: int = phase;
    var n: int = 0;             // motion ticks since t=60
    var shot_t: int = -1;
    var shots: int = 400;       // $B = 400 in MBossCard2_ECir00_at
    var px: fx = x + 32fx * cos(theta as angle);
    var py: fx = abs_y + 32fx * sin(theta as angle);
    move_to(0, px, py, EASE_LINEAR);
    loop {
        wait(1);
        n = n + 1;
        // speed: t=60->0 over 68 frames (mode1 quad-in), t=120->2 over 68 frames (mode1)
        var s: fx = 2fx;
        if n <= 60 {
            var u: fx = (n as fx) / 68fx;
            s = 2fx * (1fx - u * u);
        } else if n <= 128 {
            var u2: fx = ((n - 60) as fx) / 68fx;
            s = 0.443fx + (2fx - 0.443fx) * u2 * u2;
        }
        abs_y = abs_y - s;
        theta = theta + MB2_OMEGA;
        px = x + 32fx * cos(theta as angle);
        py = abs_y + 32fx * sin(theta as angle);
        move_to(0, px, py, EASE_LINEAR);
        if shots > 0 {
            if n == 1 { shot_t = 10 + rand(30); }   // wait(10 + RAND%30) of the shooter async
            if shot_t > 0 { shot_t = shot_t - 1; }
            if shot_t == 0 {
                // etAim(2) with 1x1 is aimed; etAngle alpha = RANDF2 * 0.5235988 rad (+-30 deg).
                var r: int = rand(65536);
                var off: int = (r - 32768) * 5461 / 32768;
                var ang: angle = aim_player() + (off as angle);
                // tap ball, color 2, speed 1.5; ANIM effect keeps position -= 4*velocity (=6px).
                _ = fire(TH16_BALL, 2,
                         px - 6fx * cos(ang), py - 6fx * sin(ang),
                         1.5fx, ang, none, none);
                shots = shots - 1;
                shot_t = 20;
            }
        }
    }
}

// st07mbs.ecl.txt:293-330 MBossCard2 (real main midboss).
async sub mb2_boss() {
    set_invuln(65535);
    set_hurtbox(24fx);          // setHurtbox(48,48)
    set_hitbox(20fx);           // setHitbox(40,40)
    wait(90);                   // source +90 label before @MBossCard2_at() async
    spawn mb2_spawner();
    loop { wait(1); }
}

// st07mbs2.ecl.txt:235-269 MBossBCard2 (real second midboss, no emitters in this card).
async sub mb2_boss_b() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    loop { wait(1); }
}

async sub mb2_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(80fx, 128fx, 1700, 0, 0, 0, mb2_boss);
    _ = spawn_enemy(0fx - 80fx, 128fx, 1700, 0, 0, 0, mb2_boss_b);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, mb2_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

